import sys


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    idx = 2
    a = []
    for _ in range(n):
        a.append([int(x) for x in data[idx:idx + m]])
        idx += m
    ops = data[idx + 1]
    for c in ops:
        h = len(a)
        w = len(a[0])
        if c == 'R':
            a = [[a[h - 1 - j][i] for j in range(h)] for i in range(w)]
        elif c == 'L':
            a = [[a[j][w - 1 - i] for j in range(h)] for i in range(w)]
        elif c == 'H':
            a = [[a[i][w - 1 - j] for j in range(w)] for i in range(h)]
        elif c == 'V':
            a = [[a[h - 1 - i][j] for j in range(w)] for i in range(h)]
        else:
            a = [[a[j][i] for j in range(h)] for i in range(w)]
    print('\n'.join(' '.join(map(str, row)) for row in a))


main()

