import sys


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    vals = [int(x) for x in data[2:2 + n * m]]
    ops = data[2 + n * m + 1]
    h, w = n, m
    pos = [(r, c) for r in range(n) for c in range(m)]
    for op in ops:
        moved = []
        for r, c in pos:
            if op == 'R':
                moved.append((c, h - 1 - r))
            elif op == 'L':
                moved.append((w - 1 - c, r))
            elif op == 'H':
                moved.append((r, w - 1 - c))
            elif op == 'V':
                moved.append((h - 1 - r, c))
            else:
                moved.append((c, r))
        pos = moved
        if op in 'RLT':
            h, w = w, h
    grid = [[None] * w for _ in range(h)]
    for k in range(n * m):
        r, c = pos[k]
        grid[r][c] = vals[k]
    out = []
    for r in range(h):
        out.append(' '.join(str(grid[r][c]) for c in range(w)))
    print('\n'.join(out))


main()

